<div id="formats" class="settings-subsection">
    <div class="flex flex-wrap items-start justify-between gap-4"><div><p class="eyebrow">Formatos y precios</p><h3 class="mt-1 text-base font-semibold">Presentaciones</h3><p class="mt-2 text-sm leading-6 text-stone-500">Un producto sencillo puede seguir usando su precio base. Añade formatos solo cuando cambie la forma de venderlo.</p></div><a href="{{ route('restaurant.menu.products.formats.create', [$restaurant, $product]) }}" class="button-secondary">Añadir formato</a></div>
    @if ($product->formats->isEmpty())<div class="mt-5 rounded-xl border border-dashed border-stone-300 bg-stone-50 px-4 py-5 text-sm text-stone-500">Todavía no hay formatos. El producto utiliza su precio base de {{ \App\CatalogMoney::format($product->price_minor) }} {{ $restaurant->currency }}.</div>@else
        <div class="mt-5 space-y-2">@foreach ($product->formats as $index => $format)<div class="flex flex-wrap items-center gap-3 rounded-xl border border-stone-200 px-3 py-3"><div class="flex items-center gap-1"><form method="POST" action="{{ route('restaurant.menu.products.formats.move', [$restaurant, $product, $format, 'up']) }}">@csrf @method('PATCH')<button class="icon-button" aria-label="Subir {{ $format->name }}" @disabled($index === 0)>↑</button></form><form method="POST" action="{{ route('restaurant.menu.products.formats.move', [$restaurant, $product, $format, 'down']) }}">@csrf @method('PATCH')<button class="icon-button" aria-label="Bajar {{ $format->name }}" @disabled($index === $product->formats->count() - 1)>↓</button></form></div><div class="min-w-0 flex-1"><p class="font-semibold">{{ $format->name }} @if ($format->is_default)<span class="badge badge-orange">Predeterminado</span>@endif @if (! $format->is_active)<span class="badge">Inactivo</span>@endif</p><p class="text-sm text-stone-500">{{ \App\CatalogMoney::format($format->price_minor) }} {{ $restaurant->currency }}</p></div><form method="POST" action="{{ route('restaurant.menu.products.formats.default', [$restaurant, $product, $format]) }}">@csrf @method('PATCH')<button class="text-button" @disabled($format->is_default || ! $format->is_active)>Predeterminado</button></form><a href="{{ route('restaurant.menu.products.formats.edit', [$restaurant, $product, $format]) }}" class="button-secondary">Editar</a></div>@endforeach</div>
